if obj.scheme != "s3":
    raise ValueError(f"The provided folder should start with s3://. Found {output_dir.path}.")

# Define the prefix for the S3 bucket
prefix = obj.path.lstrip("/").rstrip("/")

# Create an S3 client
s3 = boto3.client("s3")

# List objects in the bucket with the specified Prefix
objects = s3.list_objects_v2(Bucket=obj.netloc, Prefix=prefix + '/')

# Check if "index.json" exists among the objects
