    for object in objects["Contents"]:
        if object["Key"] == "index.json":
            raise RuntimeError(f"The directory {output_dir.path} already contains an index file.")

# If no "index.json" is found, delete all objects in the bucket
if objects["KeyCount"] > 0:
    for object in objects["Contents"]:
        s3.delete_object(Bucket=obj.netloc, Key=object["Key"])

